{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "DistributionCenter",
  "description": "Payload de cadastro de centro de distribuição via POST /multicd/distribution-centers. Wrapper de recurso: DistributionCenter. Requer MultiCD ativo na loja. Doc: https://developers.tray.com.br. NÃO-VERIFICADO contra sandbox — validar antes do merge.",
  "type": "object",
  "properties": {
    "name": {
      "type": "string",
      "maxLength": 255,
      "description": "Nome do centro de distribuição (ex.: 'CD São Paulo', 'CD Minas')."
    },
    "zip_code": {
      "type": "string",
      "format": "cep",
      "description": "CEP do endereço físico do CD, 8 dígitos numéricos sem traço. Alimenta o cálculo de frete e a regra de proximidade na seleção de CD."
    },
    "address": {
      "type": "string",
      "maxLength": 255,
      "description": "Endereço completo do CD."
    },
    "city": {
      "type": "string",
      "maxLength": 255,
      "description": "Cidade do CD."
    },
    "state": {
      "type": "string",
      "maxLength": 2,
      "pattern": "^[A-Z]{2}$",
      "description": "UF do CD, sigla de 2 letras maiúsculas (ex.: SP, MG)."
    },
    "priority": {
      "type": "integer",
      "minimum": 0,
      "description": "Prioridade na seleção de atendimento; menor número = maior prioridade."
    },
    "active": {
      "type": "integer",
      "enum": [0, 1],
      "description": "Status do CD: 1 = ativo (entra na seleção e na soma de estoque da vitrine), 0 = inativo."
    }
  },
  "required": [
    "name",
    "zip_code",
    "address",
    "city",
    "state"
  ],
  "additionalProperties": false
}
